fn jet_string_after(s: &String, sep: &str) -> String {
    match s.find(sep) {
        Some(i) => s[i + sep.len()..].to_string(),
        None => s.clone(),
    }
}
fn jet_string_before(s: &String, sep: &str) -> String {
    match s.find(sep) {
        Some(i) => s[..i].to_string(),
        None => s.clone(),
    }
}
